{
  "functions": {
    "authenticate_twitter": {
      "description": "Authenticate a user with username and password.",
      "parameters": {
        "type": "object",
        "properties": {
          "username": {"type": "string"},
          "password": {"type": "string"}
        },
        "required": ["username", "password"]
      }
    },
    "comment": {
      "description": "Comment on a tweet for the authenticated user.",
      "parameters": {
        "type": "object",
        "properties": {
          "tweet_id": {"type": "number"},
          "comment_content": {"type": "string"}
        },
        "required": ["tweet_id", "comment_content"]
      }
    },
    "follow_user": {
      "description": "Follow a user for the authenticated user.",
      "parameters": {
        "type": "object",
        "properties": {
          "username_to_follow": {"type": "string"}
        },
        "required": ["username_to_follow"]
      }
    },
    "get_tweet": {
      "description": "Retrieve a specific tweet.",
      "parameters": {
        "type": "object",
        "properties": {
          "tweet_id": {"type": "number"}
        },
        "required": ["tweet_id"]
      }
    },
    "get_tweet_comments": {
      "description": "Retrieve all comments for a specific tweet.",
      "parameters": {
        "type": "object",
        "properties": {
          "tweet_id": {"type": "number"}
        },
        "required": ["tweet_id"]
      }
    },
    "get_user_stats": {
      "description": "Get statistics for a specific user.",
      "parameters": {
        "type": "object",
        "properties": {
          "username": {"type": "string"}
        },
        "required": ["username"]
      }
    },
    "get_user_tweets": {
      "description": "Retrieve all tweets from a specific user.",
      "parameters": {
        "type": "object",
        "properties": {
          "username": {"type": "string"}
        },
        "required": ["username"]
      }
    },
    "list_all_following": {
      "description": "List all users that the authenticated user is following.",
      "parameters": {
        "type": "object",
        "properties": {}
      }
    },
    "mention": {
      "description": "Mention specified users in a tweet.",
      "parameters": {
        "type": "object",
        "properties": {
          "tweet_id": {"type": "number"},
          "mentioned_usernames": {
            "type": "array",
            "items": {"type": "string"}
          }
        },
        "required": ["tweet_id", "mentioned_usernames"]
      }
    },
    "post_tweet": {
      "description": "Post a tweet for the authenticated user.",
      "parameters": {
        "type": "object",
        "properties": {
          "content": {"type": "string"},
          "tags": {
            "type": "array",
            "items": {"type": "string"},
            "default": []
          },
          "mentions": {
            "type": "array",
            "items": {"type": "string"},
            "default": []
          }
        },
        "required": ["content"]
      }
    },
    "posting_get_login_status": {
      "description": "Get the login status of the current user.",
      "parameters": {
        "type": "object",
        "properties": {}
      }
    },
    "retweet": {
      "description": "Retweet a tweet for the authenticated user.",
      "parameters": {
        "type": "object",
        "properties": {
          "tweet_id": {"type": "number"}
        },
        "required": ["tweet_id"]
      }
    },
    "search_tweets": {
      "description": "Search for tweets containing a specific keyword.",
      "parameters": {
        "type": "object",
        "properties": {
          "keyword": {"type": "string"}
        },
        "required": ["keyword"]
      }
    },
    "unfollow_user": {
      "description": "Unfollow a user for the authenticated user.",
      "parameters": {
        "type": "object",
        "properties": {
          "username_to_unfollow": {"type": "string"}
        },
        "required": ["username_to_unfollow"]
      }
    },
    "cat": {
      "description": "Display the contents of a file of any extension from currrent directory.",
      "parameters": {
        "type": "object",
        "properties": {
          "file_name": {"type": "string"}
        },
        "required": ["file_name"]
      }
    },
    "cp": {
      "description": "Copy a file or directory from one location to another. If the destination is a directory, the source file or directory will be copied into the destination directory. Both source and destination must be local to the current directory.",
      "parameters": {
        "type": "object",
        "properties": {
          "source": {"type": "string"},
          "destination": {"type": "string"}
        },
        "required": ["source", "destination"]
      }
    },
    "diff": {
      "description": "Compare two files of any extension line by line at the current directory.",
      "parameters": {
        "type": "object",
        "properties": {
          "file_name1": {"type": "string"},
          "file_name2": {"type": "string"}
        },
        "required": ["file_name1", "file_name2"]
      }
    },
    "du": {
      "description": "Estimate the disk usage of a directory and its contents.",
      "parameters": {
        "type": "object",
        "properties": {
          "human_readable": {"type": "boolean", "default": false}
        }
      }
    },
    "echo": {
      "description": "Write content to a file at current directory or display it in the terminal.",
      "parameters": {
        "type": "object",
        "properties": {
          "content": {"type": "string"},
          "file_name": {"type": "string", "default": "None"}
        },
        "required": ["content"]
      }
    },
    "find": {
      "description": "Find any file or directories under specific path that contain name in its file name. This method searches for files of any extension and directories within a specified path that match the given name. If no name is provided, it returns all files and directories in the specified path and its subdirectories. Note: This method performs a recursive search through all subdirectories of the given path.",
      "parameters": {
        "type": "object",
        "properties": {
          "path": {"type": "string", "default": "."},
          "name": {"type": "string", "default": "None"}
        }
      }
    },
    "grep": {
      "description": "Search for lines in a file of any extension at current directory that contain the specified pattern.",
      "parameters": {
        "type": "object",
        "properties": {
          "file_name": {"type": "string"},
          "pattern": {"type": "string"}
        },
        "required": ["file_name", "pattern"]
      }
    },
    "ls": {
      "description": "List the contents of the current directory.",
      "parameters": {
        "type": "object",
        "properties": {
          "a": {"type": "boolean", "default": false}
        }
      }
    },
    "mkdir": {
      "description": "Create a new directory in the current directory.",
      "parameters": {
        "type": "object",
        "properties": {
          "dir_name": {"type": "string"}
        },
        "required": ["dir_name"]
      }
    },
    "mv": {
      "description": "Move a file or directory from one location to another.",
      "parameters": {
        "type": "object",
        "properties": {
          "source": {"type": "string"},
          "destination": {"type": "string"}
        },
        "required": ["source", "destination"]
      }
    },
    "pwd": {
      "description": "Return the current working directory path.",
      "parameters": {
        "type": "object",
        "properties": {}
      }
    },
    "rm": {
      "description": "Remove a file or directory.",
      "parameters": {
        "type": "object",
        "properties": {
          "file_name": {"type": "string"}
        },
        "required": ["file_name"]
      }
    },
    "rmdir": {
      "description": "Remove a directory at current directory.",
      "parameters": {
        "type": "object",
        "properties": {
          "dir_name": {"type": "string"}
        },
        "required": ["dir_name"]
      }
    },
    "sort": {
      "description": "Sort the contents of a file line by line.",
      "parameters": {
        "type": "object",
        "properties": {
          "file_name": {"type": "string"}
        },
        "required": ["file_name"]
      }
    },
    "tail": {
      "description": "Display the last part of a file of any extension.",
      "parameters": {
        "type": "object",
        "properties": {
          "file_name": {"type": "string"},
          "lines": {"type": "number", "default": 10}
        },
        "required": ["file_name"]
      }
    },
    "touch": {
      "description": "Create a new file of any extension in the current directory.",
      "parameters": {
        "type": "object",
        "properties": {
          "file_name": {"type": "string"}
        },
        "required": ["file_name"]
      }
    },
    "wc": {
      "description": "Count the number of lines, words, and characters in a file of any extension from current directory.",
      "parameters": {
        "type": "object",
        "properties": {
          "file_name": {"type": "string"},
          "mode": {"type": "string", "default": "l"}
        },
        "required": ["file_name"]
      }
    },
    "cd": {
      "description": "Change the current working directory to the specified folder.",
      "parameters": {
        "type": "object",
        "properties": {
          "folder": {"type": "string"}
        },
        "required": ["folder"]
      }
    }
  }
}

